/**
 * A faint full-size picture behind the content of its section (image), or nothing (none). It sits inside the
 * Block of the block, which `behind` makes `relative isolate overflow-hidden`, so the section stays the root of
 * the block (rule 01).
 */
import { type ReactNode } from "react";
import { Box } from "../primitives/box/box";
import { MediaFrame } from "../components/media-frame";

export type BackdropProps = {
  kind?: "none" | "image";
  alt?: string;
};

export function Backdrop({ kind = "none", alt = "" }: BackdropProps) {
  return (
    <>
      {((kind as string) === "image") ? (
        <Box className="pointer-events-none absolute inset-0 -z-10" data-testid="backdrop">
          <MediaFrame alt={alt} ratio="21/9" className="size-full rounded-none opacity-30" />
        </Box>
      ) : null}
    </>
  );
}
